mapper.select:
SELECT i.material_id, m.material_code, m.material_name, SUM(i.quantity - i.locked_qty) AS available_qty FROM wms_inventory i JOIN wms_location l ON l.id = i.location_id AND l.deleted_at = 0 JOIN wms_warehouse w ON w.id = l.warehouse_id AND w.deleted_at = 0 LEFT JOIN wms_material m ON m.id = i.material_id WHERE 1 = 1
AND i.material_id = #{materialId}
AND m.category_id = #{categoryId}
AND l.warehouse_id = #{warehouseId}
GROUP BY i.material_id, m.material_code, m.material_name

SELECT i.id, i.material_id, m.material_code, m.material_name, w.id AS warehouse_id, w.warehouse_code, w.warehouse_name, l.id AS location_id, l.location_code, i.batch_no, i.container_code, i.quantity, i.locked_qty, (i.quantity - i.locked_qty) AS available_qty, i.first_inbound_time FROM wms_inventory i JOIN wms_location l ON l.id = i.location_id AND l.deleted_at = 0 JOIN wms_warehouse w ON w.id = l.warehouse_id AND w.deleted_at = 0 LEFT JOIN wms_material m ON m.id = i.material_id WHERE i.quantity > 0 AND i.first_inbound_time IS NOT NULL AND i.first_inbound_time <= DATE_SUB(NOW(), INTERVAL #{overdueDays} DAY)
AND i.material_id = #{materialId}
AND m.category_id = #{categoryId}
AND l.warehouse_id = #{warehouseId}
ORDER BY i.first_inbound_time ASC LIMIT #{limit}
